package com.fernandaazevedo.support;
import com.fasterxml.jackson.databind.*; import org.springframework.stereotype.Component; import org.springframework.web.socket.*; import org.springframework.web.socket.handler.TextWebSocketHandler; import java.io.*; import java.time.*; import java.util.*; import java.util.concurrent.*;
@Component public class SupportWebSocketHandler extends TextWebSocketHandler {
 private final SupportAccessService access; private final TicketMessageRepository messages; private final SupportTicketRepository tickets; private final ObjectMapper json; private final Map<Long,Set<WebSocketSession>> rooms=new ConcurrentHashMap<>();
 public SupportWebSocketHandler(SupportAccessService a,TicketMessageRepository m,SupportTicketRepository t,ObjectMapper j){access=a;messages=m;tickets=t;json=j;}
 @Override public void afterConnectionEstablished(WebSocketSession s)throws Exception{Long id=id(s),uid=s.getAttributes().get("uid") instanceof Long x?x:null;var a=access.authorize(id,uid,false);if(a.isEmpty()){s.close(new CloseStatus(4403,"Acesso não autorizado"));return;}s.getAttributes().put("ticketId",id);s.getAttributes().put("userId",uid);s.getAttributes().put("userName",a.get().user().name);s.getAttributes().put("userRole",a.get().user().role);s.getAttributes().put("staff",a.get().staff());rooms.computeIfAbsent(id,x->ConcurrentHashMap.newKeySet()).add(s);send(s,Map.of("type","connected","ticketId",id));}
 @Override protected void handleTextMessage(WebSocketSession s,TextMessage raw)throws Exception{if(raw.getPayloadLength()>8192)return;JsonNode b=json.readTree(raw.getPayload());if(!"message".equals(b.path("type").asText()))return;String content=b.path("content").asText("").strip();boolean note=b.path("internalNote").asBoolean(false);if(content.isBlank()||content.length()>4000){send(s,Map.of("type","error","message","Mensagem inválida."));return;}if(note&&!Boolean.TRUE.equals(s.getAttributes().get("staff"))){send(s,Map.of("type","error","message","Nota interna não permitida."));return;}Long ticketId=(Long)s.getAttributes().get("ticketId");var a=access.authorize(ticketId,(Long)s.getAttributes().get("userId"),true);if(a.isEmpty()){s.close(new CloseStatus(4403,"Acesso revogado"));return;}TicketMessage m=new TicketMessage();m.ticketId=ticketId;m.senderId=a.get().user().id;m.senderName=a.get().user().name;m.senderRole=a.get().user().role;m.content=content;m.internalNote=note;m=messages.save(m);var t=a.get().ticket();t.updatedAt=LocalDateTime.now();if(!a.get().staff())t.status="WAITING_SUPPORT";tickets.save(t);Map<String,Object> event=new LinkedHashMap<>();event.put("type","message");event.put("id",m.id);event.put("senderId",m.senderId);event.put("senderName",m.senderName);event.put("senderRole",m.senderRole);event.put("content",m.content);event.put("internalNote",m.internalNote);event.put("createdAt",m.createdAt.toString());broadcast(ticketId,event,note);}
 @Override public void afterConnectionClosed(WebSocketSession s,CloseStatus st){Long id=(Long)s.getAttributes().get("ticketId");if(id!=null&&rooms.containsKey(id)){rooms.get(id).remove(s);if(rooms.get(id).isEmpty())rooms.remove(id);}}
 private void broadcast(Long id,Object payload,boolean staffOnly)throws IOException{TextMessage out=new TextMessage(json.writeValueAsString(payload));for(var s:rooms.getOrDefault(id,Set.of()))if(s.isOpen()&&(!staffOnly||Boolean.TRUE.equals(s.getAttributes().get("staff"))))s.sendMessage(out);}
 private void send(WebSocketSession s,Object p)throws IOException{s.sendMessage(new TextMessage(json.writeValueAsString(p)));} private Long id(WebSocketSession s){try{String p=s.getUri().getPath();return Long.valueOf(p.substring(p.lastIndexOf('/')+1));}catch(Exception e){return null;}}
}
